const body = $json.body ?? $json;

const projectId = body.project_id;
const activityId = body.activity_id;
const designImageUrl = body.design_image_url;
const siteImageUrl = body.site_image_url;

if (!projectId || typeof projectId !== "string") {
  throw new Error("Validation Error: project_id is required.");
}

if (!activityId || typeof activityId !== "string") {
  throw new Error("Validation Error: activity_id is required.");
}

if (!designImageUrl || typeof designImageUrl !== "string") {
  throw new Error("Validation Error: design_image_url is required.");
}

if (!siteImageUrl || typeof siteImageUrl !== "string") {
  throw new Error("Validation Error: site_image_url is required.");
}

return {
  json: {
    project_id: projectId.trim(),
    activity_id: activityId.trim(),
    design_image_url: designImageUrl.trim(),
    site_image_url: siteImageUrl.trim(),
    received_at: new Date().toISOString()
  }
};

const designUrl = $json.design_image_url;
const siteUrl = $json.site_image_url;

if (!designUrl || !siteUrl) {
  throw new Error("Comparison Error: both design and site images are required.");
}

const prompt = `
You are the Visual Execution Verification AI for an infrastructure project.

Compare the DESIGN image with the SITE image.

Your task is to determine whether the visible site execution is visually consistent
with the provided design/reference image.

Return ONLY valid JSON in exactly this structure:

{
  "asset_consistent": true,
  "view_consistent": true,
  "visual_similarity": 0.0,
  "completion_state": "NOT_STARTED | IN_PROGRESS | NEAR_COMPLETE | COMPLETE | UNCLEAR",
  "confidence": 0.0,
  "differences": []
}

Rules:
- Compare only what is visually supported by the two images.
- Do not invent missing information.
- Do not estimate a numerical construction completion percentage.
- visual_similarity must be between 0 and 1.
- confidence must be between 0 and 1.
- asset_consistent indicates whether the visible asset/structure appears consistent.
- view_consistent indicates whether the viewpoints are sufficiently comparable.
- differences must contain short, concrete visual observations.
- If the images are unclear or cannot be reliably compared, use "UNCLEAR".
- Return JSON only. No markdown. No explanation outside JSON.
`;

return {
  json: {
    ...$json,
    comparison_prompt: prompt
  }
};

const output = $json;

let result = output;

// If Gemini returned a string
if (typeof output === 'string') {
  try {
    result = JSON.parse(output);
  } catch (e) {
    throw new Error("Gemini comparison returned invalid JSON.");
  }
}

// If Gemini response contains text
if (typeof result.text === 'string') {
  try {
    result = JSON.parse(result.text);
  } catch (e) {
    throw new Error("Gemini comparison text is not valid JSON.");
  }
}

return {
  json: {
    project_id: $('Validate Comparison Input').item.json.project_id,
    activity_id: $('Validate Comparison Input').item.json.activity_id,

    asset_consistent: Boolean(result.asset_consistent),
    view_consistent: Boolean(result.view_consistent),

    visual_similarity: Number(
      result.visual_similarity ?? 0
    ),

    completion_state:
      result.completion_state ?? "UNCLEAR",

    confidence: Number(
      result.confidence ?? 0
    ),

    differences: Array.isArray(result.differences)
      ? result.differences
      : []
  }
};

const data = $json;

if (!data.project_id) {
  throw new Error("Validation Error: project_id is missing.");
}

if (!data.activity_id) {
  throw new Error("Validation Error: activity_id is missing.");
}

const similarity = Number(data.visual_similarity);
const confidence = Number(data.confidence);

if (!Number.isFinite(similarity) || similarity < 0 || similarity > 1) {
  throw new Error(
    "Validation Error: visual_similarity must be between 0 and 1."
  );
}

if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
  throw new Error(
    "Validation Error: confidence must be between 0 and 1."
  );
}

const allowedStates = [
  "NOT_STARTED",
  "IN_PROGRESS",
  "NEAR_COMPLETE",
  "COMPLETE",
  "UNCLEAR"
];

if (!allowedStates.includes(data.completion_state)) {
  throw new Error(
    `Validation Error: invalid completion_state: ${data.completion_state}`
  );
}

if (typeof data.asset_consistent !== "boolean") {
  throw new Error(
    "Validation Error: asset_consistent must be boolean."
  );
}

if (typeof data.view_consistent !== "boolean") {
  throw new Error(
    "Validation Error: view_consistent must be boolean."
  );
}

if (!Array.isArray(data.differences)) {
  throw new Error(
    "Validation Error: differences must be an array."
  );
}

return {
  json: {
    ...data,
    validation_status: "VALID",
    validated_at: new Date().toISOString()
  }
};

const data = $json;

return {
  json: {
    project_id: data.project_id,
    activity_id: data.activity_id,

    asset_consistent: data.asset_consistent,
    view_consistent: data.view_consistent,

    visual_similarity: data.visual_similarity,

    completion_state: data.completion_state,

    confidence: data.confidence,

    differences: data.differences,

    validation_status: data.validation_status,

    comparison_status: "COMPLETED",

    compared_at: new Date().toISOString()
  }
};

